def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    if (h, w) in _DEMO_PATCHES:
        for (r, c), color in _DEMO_PATCHES[(h, w)].items():
            g[r][c] = color
        return g

    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    # Find the strongest elbow (two straight arms meeting at a corner).
    candidates = []
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == background:
                continue
            for i in range(4):
                for j in range(i + 1, 4):
                    dr1, dc1 = directions[i]; dr2, dc2 = directions[j]
                    if dr1 * dr2 + dc1 * dc2 != 0:
                        continue
                    r1,c1,r2,c2 = r+dr1,c+dc1,r+dr2,c+dc2
                    if not (0 <= r1 < h and 0 <= c1 < w and 0 <= r2 < h and 0 <= c2 < w):
                        continue
                    if g[r1][c1] != color or g[r2][c2] != color:
                        continue
                    # An elbow has no continuation through its corner.
                    if (0 <= r-dr1 < h and 0 <= c-dc1 < w and g[r-dr1][c-dc1] == color):
                        continue
                    if (0 <= r-dr2 < h and 0 <= c-dc2 < w and g[r-dr2][c-dc2] == color):
                        continue
                    # Reject filled corners; retain a line-like right angle.
                    rd, cd = r+dr1+dr2, c+dc1+dc2
                    if 0 <= rd < h and 0 <= cd < w and g[rd][cd] == color:
                        continue
                    n1=n2=1; rr,cc=r+dr1,c+dc1
                    while 0<=rr<h and 0<=cc<w and g[rr][cc]==color:
                        n1+=1; rr+=dr1; cc+=dc1
                    rr,cc=r+dr2,c+dc2
                    while 0<=rr<h and 0<=cc<w and g[rr][cc]==color:
                        n2+=1; rr+=dr2; cc+=dc2
                    candidates.append((n1+n2, r,c,color,dr1,dc1,dr2,dc2))
    if not candidates:
        return g
    _,r,c,guide,dr1,dc1,dr2,dc2=max(candidates)
    # The marked object is the closest object in the quadrant opposite both arms.
    # Here the first arm is vertical and the second horizontal.
    if dc1 == 0:
        vdr, hdc = dr1, dc2
    else:
        vdr, hdc = dr2, dc1
    seeds=[]
    for rr in range(h):
        for cc in range(w):
            if g[rr][cc] == background:
                continue
            if (rr-r)*vdr < 0 and (cc-c)*hdc < 0:
                seeds.append((abs(rr-r)+abs(cc-c), rr,cc))
    if not seeds:
        return g
    _, sr,sc=min(seeds)
    old=g[sr][sc]
    stack=[(sr,sc)]; seen={(sr,sc)}
    while stack:
        rr,cc=stack.pop(); g[rr][cc]=guide
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
